#include <bits/stdc++.h>
using namespace std;

class CF884F {
public:
    CF884F() { ios::sync_with_stdio(false); cin.tie(nullptr); }
    void main() {
        int n_input;
        cin >> n_input;
        int n = n_input / 2;

        const int A = 26;
        const int INF = 0x3f3f3f3f;

        int n_ = 1 + n + A + 1;
        int m_ = n + n * A + A;

        vector<int> oo(1 + m_ * 2), oh(1 + m_ * 2);
        vector<int> ii(n), jj(n), cc(n << 1), cost(n), cost_(n);
        vector<int> pi(n_), dd(n_), ff(n_);
        vector<int> ae(n_), pq(n_ + 1, 0), iq(n_, 0);
        int m = 0;

        auto link = [&](int o, int h) {
            oo[++m] = o;
            oh[m] = h;
            return m;
        };

        auto link_ = [&](int i, int j, int c, int co) {
            int h = m++;
            ii[h] = i;
            jj[h] = j;
            cc[h << 1] = c;
            cost[h] = co;
            ae[i] = link(ae[i], h << 1);
            ae[j] = link(ae[j], h << 1 | 1);
        };

        auto less = [&](int u, int v) {
            return pi[u] < pi[v] || (pi[u] == pi[v] && dd[u] < dd[v]);
        };

        auto i2 = [&](int i) {
            i *= 2;
            if (i > m) return 0;
            int j = i / 2;
            if (j < m / 2 && less(pq[iq[pq[j]]], pq[iq[pq[j + 1]]])) {
                return (i / 2) + 1;
            }
            return i / 2;
        };

        auto pq_up = [&](int u) {
            int i = iq[u], j, v;
            while ((j = i / 2) > 0 && less(u, v = pq[j])) {
                pq[iq[v]] = i;
                i = j;
            }
            pq[iq[u] = i] = u;
        };

        auto pq_dn = [&](int u) {
            int i = iq[u], j, v;
            while ((j = i2(i)) > 0 && less(v = pq[j], u)) {
                pq[iq[v]] = i;
                i = j;
            }
            pq[iq[u] = i] = u;
        };

        auto pq_add_last = [&](int u) {
            pq[++(*pq_endp)] = u;
            iq[u] = *pq_endp;
        };

        auto pq_remove_first = [&]() {
            int u = pq[1], v = pq[(*pq_endp)--];
            if (v != u) {
                iq[v] = 1;
                pq_dn(v);
            }
            iq[u] = 0;
            return u;
        };

        int *pq_endp = &pq[0];

        auto dijkstra = [&](int s, int t) {
            std::fill(pi.begin(), pi.end(), INF);
            pi[s] = 0;
            pq_add_last(s);
            int cnt = 0;
            while (*pq_endp > 0) {
                int i = pq_remove_first();
                int d = dd[i] + 1;
                for (int o = ae[i]; o != 0; o = oo[o]) {
                    int h_ = oh[o];
                    if (cc[h_] > 0) {
                        int h = h_ >> 1;
                        int j_node = i ^ ii[h] ^ jj[h];
                        int p = pi[i] + (((h_ & 1) == 0) ? cost_[h] : -cost_[h]);
                        if (pi[j_node] > p || (pi[j_node] == p && dd[j_node] > d)) {
                            if (pi[j_node] == INF)
                                pq_add_last(j_node);
                            pi[j_node] = p;
                            dd[j_node] = d;
                            ff[j_node] = h_;
                            pq_up(j_node);
                        }
                    }
                }
            }
            return pi[t] != INF;
        };

        auto trace = [&](int s, int t) {
            while (t != s) {
                int h_ = ff[t], h = h_ >> 1;
                cc[h_]--;
                cc[h_ ^ 1]++;
                t ^= ii[h] ^ jj[h];
            }
            return 1;
        };

        auto edmonds_karp = [&]() {
            for (int h = 0; h < m; h++) {
                int i = ii[h], j = jj[h];
                pi[j] = min(pi[j], pi[i] + cost[h]);
            }
            for (int h = 0; h < m; h++) {
                int i = ii[h], j = jj[h];
                cost_[h] = cost[h] + pi[i] - pi[j];
            }
            int f = 0;
            while (dijkstra(0, n_ - 1)) {
                f += trace(0, n_ - 1);
                for (int h = 0; h < m; h++) {
                    int i = ii[h], j = jj[h];
                    if (pi[i] != INF && pi[j] != INF) {
                        cost_[h] += pi[i] - pi[j];
                    }
                }
            }
            int ans = 0;
            for (int h = 0; h < m; h++) {
                ans += cc[h << 1 | 1] * cost[h];
            }
            return ans;
        };

        // Read input
        string s;
        cin >> s;
        vector<char> cc_chars(s.begin(), s.end());
        vector<int> bb(n * 2);
        for (int i = 0; i < n * 2; i++) {
            cin >> bb[i];
        }

        for (int i = 0; i < n; i++)
            link_(0, 1 + i, 2, 0);

        for (int i = 0; i < n; i++) {
            int j = n * 2 - 1 - i;
            int ai = cc_chars[i] - 'a';
            int aj = cc_chars[j] - 'a';
            for (int a = 0; a < A; a++) {
                int b;
                if (a == ai && a == aj)
                    b = max(bb[i], bb[j]);
                else if (a == ai)
                    b = bb[i];
                else if (a == aj)
                    b = bb[j];
                else
                    b = 0;
                link_(1 + i, 1 + n + a, 1, -b);
            }
        }

        vector<int> kk(A, 0);
        for (int i = 0; i < n * 2; i++) {
            int a = cc_chars[i] - 'a';
            kk[a]++;
        }

        for (int a = 0; a < A; a++)
            link_(1 + n + a, n_ - 1, kk[a], 0);

        int result = -edmonds_karp();
        cout << result << "\n";
    }
};

